#!/usr/bin/env bash
# Install the Blocker local CA into the system trust store. Needed for the
# HTTPS block page and for HTTPS path rules to appear cleanly (no certificate
# warning). The CA is generated by blockerd/blocker-proxy on first run.
set -euo pipefail

CA_SRC="/etc/blocker/ca.crt"

msg() { printf '\033[1;34m==>\033[0m %s\n' "$*"; }
warn() { printf '\033[1;33m[!]\033[0m %s\n' "$*"; }

if [[ $EUID -ne 0 ]]; then
    echo "Please run as root:  sudo $0"
    exit 1
fi

if [[ ! -f "$CA_SRC" ]]; then
    echo "CA not found at $CA_SRC."
    echo "Start the daemon once so it is generated:  sudo systemctl start blockerd"
    exit 1
fi

msg "Installing the Blocker CA into the system trust store…"
if command -v update-ca-certificates >/dev/null 2>&1; then
    install -D -m 0644 "$CA_SRC" /usr/local/share/ca-certificates/blocker.crt
    update-ca-certificates
elif command -v update-ca-trust >/dev/null 2>&1; then
    install -D -m 0644 "$CA_SRC" /etc/pki/ca-trust/source/anchors/blocker.crt
    update-ca-trust
else
    warn "Unknown trust-store tooling; install $CA_SRC into your system CA store manually."
fi

cat <<'EOF'

==> System trust updated. Browsers often keep their OWN trust store, so also:

   Firefox:  about:config  ->  security.enterprise_roots.enabled = true
             (makes Firefox trust the system CA)

   Chrome/Chromium (NSS), run AS YOUR USER (not root):
     certutil -d sql:$HOME/.pki/nssdb -A -t "C,," -n "Blocker CA" -i /etc/blocker/ca.crt

Without this, HTTPS blocked sites will show a certificate warning instead of
the block page (plain-HTTP sites and domain/subdomain DNS blocking are
unaffected).
EOF
